/* SwitchRecomp: our .ini's values into ScarletNX's settings (g_settings, generated by its settingsgen into the build's
   shaderdec/ folder), set by snxvk_glue.c before the renderer starts. Paths this build leaves out stay off: FFmpeg
   video decode, and the shipped-shader pass unless prebuild_shaders asks for it. */
#include "snx_settings.h"
#include "nx/memory/own.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
/* SWR_VK_RENDERDOC=PREFIX and SWR_VK_RENDERDOC_FRAMES=N,Ms,...: RenderDoc captures of chosen frames (vk/renderdoc.c),
   for debugging a scripted run; RenderDoc's folder must be on PATH. SWR_VK_SHADER_CORPUS=DIR: every shader's code
   and key, for tools/snx_shaderc.c (gpu/shader/corpus.c) */
static void env_text(char* to, size_t size, const char* name) {
    const char* e = getenv(name);
    if (e && *e) snprintf(to, size, "%s", e);
}
void swr_settings_set(float resolution, int shadows, int vsync, int anisotropy, int recording_thread) {
    env_text(g_settings.render_doc_captures, sizeof g_settings.render_doc_captures, "SWR_VK_RENDERDOC");
    env_text(g_settings.render_doc_frames, sizeof g_settings.render_doc_frames, "SWR_VK_RENDERDOC_FRAMES");
    env_text(g_settings.shader_corpus, sizeof g_settings.shader_corpus, "SWR_VK_SHADER_CORPUS");
    g_settings.resolution_scale = resolution;
    g_settings.shadows = shadows;
    g_settings.vsync = vsync;
    g_settings.anisotropic_filtering = anisotropy;
    g_settings.vulkan_recording_thread = recording_thread;
    g_settings.prepare_shaders = 0;
    g_settings.vulkan_video_decode = 0;
    g_settings.guest_memory = 1; /* copied: the UMA import path (vk/uma.c) needs platform memory hooks our runtime lacks */
}
int swr_settings_recording_thread(void) { return g_settings.vulkan_recording_thread; }
/* [Graphics] prebuild_shaders: the shipped-shader pass over the RomFS's system/shd (snxvk_glue.c romfs_files), in the
   background (1, not 2: no count first, no screen) */
void swr_settings_prepare(int on) { g_settings.prepare_shaders = on ? 1 : 0; }
/* [Graphics] profile=1: also the GPU's time per rendering pass and between passes, in the log every 10 s (gpuprof.c),
   and the buffer cache's copies and waits every 600 presents (buffer.c) */
void swr_settings_gpu_profile(int on) {
    g_settings.gpu_profile = on ? 1 : 0;
    g_settings.buffer_copy_stats = on ? 1 : 0;
}
/* SwitchRecomp's own native Vulkan tunings, [Graphics] vk_* keys (main.c), each 1 = on: see where they are read */
int g_swr_fast_writeback = 1; /* writeback.c: a chunk guest memory left alone lands in one copy */
int g_swr_dynamic_offsets = 1; /* pipeline.c: busy buffer bindings take their offsets at the bind */
void swr_settings_tuning(const char* key, int on) {
    if (!strcmp(key, "vk_fast_writeback")) g_swr_fast_writeback = on;
    if (!strcmp(key, "vk_dynamic_offsets")) g_swr_dynamic_offsets = on;
    if (!strcmp(key, "vk_async_pipelines")) g_settings.async_pipelines = on ? 1 : 0; /* settings.txt Async pipelines */
    if (!strcmp(key, "vk_memory_traps")) g_swr_memory_traps = on; /* memory/own_win.c: GPU results stay on the GPU */
}
